var content = K.Stack(10,
    new Grid
    {
        ColumnDefinitions = new ColumnDefinitions("*,Auto"),
        Children =
        {
            K.Stack(2,
                K.Text("Compare our pricing page with four competitors", "arc-heading", 560),
                K.Caption("Lead: Claude Opus 5.5 · 4 worker lanes · 48.2k tokens · $0.21")),
            K.Row(8, concurrencyControl, runAgain)
        }
    },
    K.Divider(2),
    K.Row(7,
        new ArcIcon { Icon = "target", Size = 13, Foreground = K.Brush(ArcTokens.Accent) },
        K.Caption("Plan"),
        K.Caption("4 subtasks · one retry on Check enterprise terms"),
        K.Pill("1 retry", ArcBadgeTone.Warning)),
    lanesHost,
    totals,
    status);

return K.Surface(new Border { Child = content, MaxWidth = 980 }, new Thickness(22, 15, 22, 15));

for (var index = 0; index < Lanes.Length; index++)
{
    var lane = Lanes[index];
    var queued = index >= concurrency;          // 超出并发上限的排到 Queued
    var state = queued ? "Queued" : lane.Status;

    var body = K.Stack(5,
        K.Row(5, K.Mark("anthropic", 16), K.Caption(lane.Model)),
        K.Text(lane.Subtask, "arc-caption", 170),
        K.Row(4, new ArcIcon { Icon = "wand-2", Size = 10 }, K.Caption(lane.Tool)),
        K.Mono(lane.Output, 10.5),
        K.Row(4,
            new ArcIcon { Icon = state == "Returned" ? "circle-check" : queued ? "clock" : "loader-circle", Size = 11 },
            K.Caption(state)),
        K.Caption($"{lane.Tokens} tokens · {lane.Time}"));

    var card = new Border
    {
        BorderThickness = new Thickness(1),
        CornerRadius = new CornerRadius(12),
        Padding = new Thickness(10, 8, 10, 8),
        Opacity = queued ? 0.6 : 1,
        Child = body
    };
    laneCells[index] = card;
}
